'use client';

// SPDX-License-Identifier: MIT
// Copyright (c) 2026 Web Stylebook

import { useId, type HTMLAttributes, type ReactNode } from 'react';
import '../theme.css';
import './progress-bar.css';

function cx(...parts: Array<string | false | null | undefined>) {
  return parts.filter(Boolean).join(' ');
}

export type ProgressTone = 'accent' | 'info' | 'positive' | 'caution' | 'critical';

export interface ProgressBarProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  /** Names the bar for everyone. Visually hidden with hideLabel. */
  label: string;
  hideLabel?: boolean;
  value?: number;
  max?: number;
  /** Text beside the label, such as "3.2 GB of 5 GB". Defaults to the percentage. */
  valueText?: string;
  tone?: ProgressTone;
  /** Work with no known end. A segment travels along the track. */
  indeterminate?: boolean;
}

/** How far a task has come, or how much of a limit is used. */
export function ProgressBar({
  label,
  hideLabel = false,
  value = 0,
  max = 100,
  valueText,
  tone = 'accent',
  indeterminate = false,
  className,
  ...rest
}: ProgressBarProps) {
  const labelId = useId();
  const percent = max > 0 ? Math.min(100, Math.max(0, (value / max) * 100)) : 0;
  const shownValue = indeterminate ? valueText : (valueText ?? `${Math.round(percent)}%`);

  return (
    <div {...rest} className={cx('ws-progress', className)} data-tone={tone}>
      <div className="ws-progress__head" data-hidden={hideLabel ? '' : undefined}>
        <span className="ws-progress__label" id={labelId}>
          {label}
        </span>
        {shownValue ? <span className="ws-progress__value">{shownValue}</span> : null}
      </div>
      <div
        className="ws-progress__track"
        role="progressbar"
        aria-labelledby={labelId}
        aria-valuemin={indeterminate ? undefined : 0}
        aria-valuemax={indeterminate ? undefined : max}
        aria-valuenow={indeterminate ? undefined : value}
        aria-valuetext={shownValue || undefined}
        data-indeterminate={indeterminate ? '' : undefined}
      >
        <span className="ws-progress__fill" style={indeterminate ? undefined : { transform: `translateX(${percent - 100}%)` }} />
      </div>
    </div>
  );
}

export interface StackedBarSegment {
  label: string;
  value: number;
  tone: ProgressTone;
  /** Text after the label. Defaults to the value. */
  valueText?: ReactNode;
}

export interface StackedBarProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  /** Names the list of segments for screen readers. */
  label: string;
  segments: StackedBarSegment[];
  /** The whole bar. Defaults to the sum of the segments; a larger max leaves free space. */
  max?: number;
}

/** Parts of a whole. The legend carries the values, so the bar itself is decorative. */
export function StackedBar({ label, segments, max, className, ...rest }: StackedBarProps) {
  const sum = segments.reduce((total, segment) => total + segment.value, 0);
  const whole = Math.max(max ?? sum, sum);
  // Grow values that add up to 1, so fractional inputs still fill the bar.
  const share = (value: number) => (whole > 0 ? value / whole : 0);
  const free = whole - sum;

  return (
    <div {...rest} className={cx('ws-stacked', className)}>
      <div className="ws-stacked__bar" aria-hidden="true">
        {segments
          .filter((segment) => segment.value > 0)
          .map((segment) => (
            <span key={segment.label} className="ws-stacked__part" data-tone={segment.tone} style={{ flexGrow: share(segment.value) }} />
          ))}
        {free > 0 ? <span className="ws-stacked__free" style={{ flexGrow: share(free) }} /> : null}
      </div>
      <ul className="ws-stacked__legend" aria-label={label}>
        {segments.map((segment) => (
          <li key={segment.label} className="ws-stacked__item">
            <span className="ws-stacked__swatch" data-tone={segment.tone} aria-hidden="true" />
            <span className="ws-stacked__name">{segment.label}</span>
            <span className="ws-stacked__amount">{segment.valueText ?? segment.value}</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

/* SPDX-License-Identifier: MIT. Copyright (c) 2026 Web Stylebook */

.ws-progress,
.ws-stacked {
  box-sizing: border-box;
  display: grid;
  width: 100%;
  min-width: 0;
  gap: var(--ws-space-2);
  color: var(--ws-color-text);
  font-family: var(--ws-font-sans);
  font-size: var(--ws-text-sm);
  line-height: var(--ws-leading-tight);
}

.ws-progress[data-tone='accent'],
.ws-stacked__part[data-tone='accent'],
.ws-stacked__swatch[data-tone='accent'] {
  --ws-progress-color: var(--ws-color-accent);
}

.ws-progress[data-tone='info'],
.ws-stacked__part[data-tone='info'],
.ws-stacked__swatch[data-tone='info'] {
  --ws-progress-color: var(--ws-color-info-mark);
}

.ws-progress[data-tone='positive'],
.ws-stacked__part[data-tone='positive'],
.ws-stacked__swatch[data-tone='positive'] {
  --ws-progress-color: var(--ws-color-positive-mark);
}

.ws-progress[data-tone='caution'],
.ws-stacked__part[data-tone='caution'],
.ws-stacked__swatch[data-tone='caution'] {
  --ws-progress-color: var(--ws-color-caution-mark);
}

.ws-progress[data-tone='critical'] {
  --ws-progress-color: var(--ws-color-critical-mark);
}

/* A deeper red beside caution: the two marks are nearly the same color for
   someone with red-green color blindness. */
.ws-stacked__part[data-tone='critical'],
.ws-stacked__swatch[data-tone='critical'] {
  --ws-progress-color: var(--ws-color-critical-text);
}

.ws-progress__head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--ws-space-3);
}

.ws-progress__head[data-hidden] {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.ws-progress__label {
  min-width: 0;
  font-weight: var(--ws-weight-medium);
}

.ws-progress__value {
  flex: none;
  color: var(--ws-color-text-muted);
  font-variant-numeric: tabular-nums;
}

/* The fill is a full-width bar moved sideways, so its rounded end keeps its
   shape at any value and the change runs on the compositor. */
.ws-progress__track {
  position: relative;
  height: 6px;
  overflow: hidden;
  border-radius: var(--ws-radius-full);
  background: var(--ws-color-surface-hover);
}

.ws-progress__fill {
  display: block;
  width: 100%;
  height: 100%;
  border-radius: inherit;
  background: var(--ws-progress-color);
  transition:
    transform var(--ws-duration-slow) var(--ws-ease),
    background-color var(--ws-duration) var(--ws-ease);
}

.ws-progress__track[data-indeterminate] .ws-progress__fill {
  width: 36%;
  animation: ws-progress-travel 1400ms var(--ws-ease) infinite alternate;
}

@keyframes ws-progress-travel {
  from {
    transform: translateX(-20%);
  }

  to {
    transform: translateX(198%);
  }
}

@media (prefers-reduced-motion: reduce) {
  /* Still reads as active: a held segment in the middle of the track. */
  .ws-progress__track[data-indeterminate] .ws-progress__fill {
    animation: none;
    transform: translateX(89%);
  }
}

.ws-stacked {
  gap: var(--ws-space-3);
}

.ws-stacked__bar {
  display: flex;
  gap: 2px;
  height: 10px;
  overflow: hidden;
  border-radius: var(--ws-radius-full);
  background: var(--ws-color-surface-hover);
}

/* Shares are flex-grow values, so the gaps come out of the bar and the last
   segment always ends at the bar's edge. */
.ws-stacked__part,
.ws-stacked__free {
  flex: 0 1 0;
  transition: flex-grow var(--ws-duration-slow) var(--ws-ease);
}

.ws-stacked__part {
  min-width: 3px;
  background: var(--ws-progress-color);
}

.ws-stacked__legend {
  display: flex;
  flex-wrap: wrap;
  gap: var(--ws-space-2) var(--ws-space-4);
  margin: 0;
  padding: 0;
  list-style: none;
}

.ws-stacked__item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}

.ws-stacked__swatch {
  flex: none;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--ws-progress-color);
}

.ws-stacked__name {
  color: var(--ws-color-text-muted);
}

.ws-stacked__amount {
  font-weight: var(--ws-weight-medium);
  font-variant-numeric: tabular-nums;
}
